import{_ as n,a0 as o,w as r,s as u,I as s,x as e,a1 as p,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"所有人的 DevOps | LCTT x X-CMD","titleTemplate":false,"description":"所有人的 DevOps | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"所有人的 DevOps | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"所有人的 DevOps | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 DevOps is for everyone","title":"所有人的 DevOps","tag":"201812","desc":""},"relativePath":"201812/20181121 DevOps is for everyone.md","filePath":"[post].md"}'),v={name:"201812/20181121 DevOps is for everyone.md"};function a(f,t,D,m,O,g){const l=o("Link");return r(),u("div",null,[t[31]||(t[31]=s("h1",{id:"所有人的-devops",tabindex:"-1"},[e("所有人的 DevOps "),s("a",{class:"header-anchor",href:"#所有人的-devops","aria-label":"Permalink to “所有人的 DevOps”"},"​")],-1)),t[32]||(t[32]=s("blockquote",null,[s("p",null,"讓一名非工程師來解釋為什麼你不必成為一位開發者或運維就能愛上 DevOps。")],-1)),t[33]||(t[33]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/team-game-play-inclusive-diversity-collaboration.png?itok=8sUXV7W1",alt:""})],-1)),s("p",null,[t[1]||(t[1]=e("我從未做過開發或運維的工作 —— 那怎麼我在寫一篇關於 ",-1)),p(l,{href:"https://opensource.com/resources/devops"},{default:i(()=>[...t[0]||(t[0]=[e("DevOps",-1)])]),_:1}),t[2]||(t[2]=e(" 的文章？我一直都對計算機和技術有興趣。我還對社羣、心理學以及幫助他人充滿熱情。當我第一次聽到 DevOps 時，這個概念激起了我的興趣，因為它看起來融合了很多我感興趣的東西，即便我是不寫代碼的。",-1))]),t[34]||(t[34]=d('<p>我的第一台電腦是 TRS-80，我喜歡在上面編寫 BASIC 程序。我只上過兩門我的高中開設的計算機編程課程。若干年後，我創辦了一家計算機公司。我定製郵件標籤和信紙，並建立了一個數據庫來存儲地址。</p><p>問題是我並不能從寫代碼中獲得享受。我想要教育和幫助人們，我沒法將寫代碼看作這樣的一個機會。是的，技術可以幫助人們並改變生活，但是寫代碼沒有點燃我的熱情。我需要對我的工作感到興奮並做我喜歡的事情。</p><p>我發現我愛 DevOps。對我而言，DevOps 指的是：</p><ul><li>文化，而不是代碼</li><li>過程，而不是結果</li><li>建立一個所有人可以持續提升的環境</li><li>溝通與合作，而不是獨立工作</li></ul><p>歸根結底，DevOps 是指成為社區工作的一部分，實現共同的目標。DevOps 融合了心理學、社羣、技術。DevOps 不是一個職位名稱，它是一種生活和工作的哲學。</p><h3 id="找到我的社羣" tabindex="-1">找到我的社羣 <a class="header-anchor" href="#找到我的社羣" aria-label="Permalink to “找到我的社羣”">​</a></h3>',6)),s("p",null,[t[4]||(t[4]=e("快四年前，我在西雅圖參加了我的第一個 ",-1)),p(l,{href:"https://www.devopsdays.org/"},{default:i(()=>[...t[3]||(t[3]=[e("DevOps 日",-1)])]),_:1}),t[5]||(t[5]=e(" 會議。我感覺我找到了我的社羣。我覺得受到了歡迎和接受，儘管我從事營銷工作而且沒有計算機科學文憑。我可以從心理學和技術中尋找樂趣。",-1))]),s("p",null,[t[7]||(t[7]=e("在 DevOps 日，我學到了 ",-1)),p(l,{href:"https://itrevolution.com/the-three-ways-principles-underpinning-devops/"},{default:i(()=>[...t[6]||(t[6]=[e("DevOps“三步工作法”",-1)])]),_:1}),t[8]||(t[8]=e(" —— 流動、反饋、持續實驗和學習 —— 以及新（對我而言）的概念，如 Kaizen（改善）和 Kaikaku（改革）。隨着我的學習深入，我發現我在説這樣的話，“我是這樣做的！我都不知道這樣做還有個名字！”",-1))]),s("p",null,[p(l,{href:"https://en.wikipedia.org/wiki/Kaizen"},{default:i(()=>[...t[9]||(t[9]=[e("Kaizen（改善）",-1)])]),_:1}),t[11]||(t[11]=e("是持續改進和學習的實踐。小的量變積累隨着時間的推移可以引起質變。我發現它和卡羅爾·德韋克的",-1)),p(l,{href:"https://en.wikipedia.org/wiki/Mindset#Fixed_and_growth"},{default:i(()=>[...t[10]||(t[10]=[e("成長型思維",-1)])]),_:1}),t[12]||(t[12]=e("的想法很相似。人們不是生來就是專家。在某方面擁有經驗需要花費時間、練習，以及常常還有失敗。承認增量的改善對確保我們不會放棄是很有必要的。",-1))]),s("p",null,[t[14]||(t[14]=e("另一方面，",-1)),p(l,{href:"https://en.wikipedia.org/wiki/Kaikaku"},{default:i(()=>[...t[13]||(t[13]=[e("Kaikaku（改革）",-1)])]),_:1}),t[15]||(t[15]=e("的概念是指，長時間的小的改變有時不能起作用，你需要做一些完全的或破壞性的改變。在沒有找到下份工作前就辭職或移居新城市就足夠有破壞性 —— 是的，兩者我都做過。但這些徹底的改變收穫巨大。如果我沒有辭職並休息一段時間，我也許不會接觸到 DevOps。等我決定繼續工作的時候，我一直聽到 DevOps，我開始研究它。這引導我參加了我的第一個 DevOps 日，從那裏我開始看到我的所有熱情開始聚集。從那時起，我已經參加了五次 DevOps 日活動，並且定期撰寫關於 DevOps 話題的文章。",-1))]),t[35]||(t[35]=s("h3",{id:"將三步工作法用到工作中",tabindex:"-1"},[e("將三步工作法用到工作中 "),s("a",{class:"header-anchor",href:"#將三步工作法用到工作中","aria-label":"Permalink to “將三步工作法用到工作中”"},"​")],-1)),t[36]||(t[36]=s("p",null,"改變是困難的，學習新事物可以聽起來很嚇人。DevOps 的三步工作法提供了一個管理改變的框架。比如：信息流動是怎樣的？是什麼驅動着你做出改變？一旦你認為一個改變是必需的，你如何獲得這個改變是否正確的反饋？你如何知道你在取得進展？反饋是必要的，並且應該包含積極和有建設性的要素。困難的地方在於保證建設性的要素不要重於積極要素。",-1)),t[37]||(t[37]=s("p",null,"對我而言，第三步 —— 持續實驗和學習 —— 是 DevOps 最重要的部分。有一個可以自由地實驗和冒險的環境，人們可以獲得意想不到的結果。有時這些結果是好的，有時不是太好 —— 但這沒事。創建一個可以接受失敗結果的環境可以鼓勵人們冒險。我們都應該力爭定期的持續實驗和學習。",-1)),t[38]||(t[38]=s("p",null,"DevOps 的三步工作法提供了一個嘗試，獲得反饋，以及從錯誤中獲取經驗的方法。幾年前，我的兒子告訴我，“我從來就沒想做到最好，因為那樣我就沒法從我的錯誤中學到東西了。”我們都會犯錯，從中獲得經驗幫助我們成長和改善。如果我們的文化不支持嘗試和學習，我們就不會願意去犯錯。",-1)),t[39]||(t[39]=s("h3",{id:"成為社區的一部分",tabindex:"-1"},[e("成為社區的一部分 "),s("a",{class:"header-anchor",href:"#成為社區的一部分","aria-label":"Permalink to “成為社區的一部分”"},"​")],-1)),t[40]||(t[40]=s("p",null,"我已經在技術領域工作了超過 20 年，直到我發現 DevOps 社區前，我還經常感覺自己是個外行。如果你像我一樣——對技術充滿熱情，但不是工程和運維那方面——你仍然可以成為 DevOps 的一部分，即便你從事的是銷售、營銷、產品營銷、技術寫作、支持或其他工作。DevOps 是屬於所有人的。",-1)),t[41]||(t[41]=s("hr",null,null,-1)),s("p",null,[t[17]||(t[17]=e("via: ",-1)),p(l,{href:"https://opensource.com/article/18/11/how-non-engineer-got-devops"},{default:i(()=>[...t[16]||(t[16]=[e("https://opensource.com/article/18/11/how-non-engineer-got-devops",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("作者：",-1)),p(l,{href:"https://opensource.com/users/dawnparzych"},{default:i(()=>[...t[18]||(t[18]=[e("Dawn Parych",-1)])]),_:1}),t[23]||(t[23]=e(" 選題：",-1)),p(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[19]||(t[19]=[e("lujun9972",-1)])]),_:1}),t[24]||(t[24]=e(" 譯者：",-1)),p(l,{href:"https://github.com/alim0x"},{default:i(()=>[...t[20]||(t[20]=[e("alim0x",-1)])]),_:1}),t[25]||(t[25]=e(" 校對：",-1)),p(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[21]||(t[21]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[28]||(t[28]=e("本文由 ",-1)),p(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[26]||(t[26]=[e("LCTT",-1)])]),_:1}),t[29]||(t[29]=e(" 原創編譯，",-1)),p(l,{href:"https://linux.cn/"},{default:i(()=>[...t[27]||(t[27]=[e("Linux中國",-1)])]),_:1}),t[30]||(t[30]=e(" 榮譽推出",-1))])])}const w=n(v,[["render",a]]);export{x as __pageData,w as default};
